import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.Di-jvWLj.js";const h=JSON.parse('{"title":"Errors","description":"","frontmatter":{},"headers":[],"relativePath":"guide/errors.md","filePath":"guide/errors.md","lastUpdated":1793100831000}'),s={name:"guide/errors.md"};function n(d,e,c,l,p,i){return t(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h1><p>Every error chamvi throws extends <code>ChamviError</code>, which extends ebec&#39;s <code>BaseError</code>. Each carries a <code>code</code>; the codes are exported as <code>ErrorCode</code>.</p><table tabindex="0"><thead><tr><th>Class</th><th><code>ErrorCode</code></th><th>Code</th><th>Thrown when</th></tr></thead><tbody><tr><td><code>InvalidAgentDefinitionError</code></td><td><code>INVALID_AGENT_DEFINITION</code></td><td><code>invalid_agent_definition</code></td><td>An agent or channel name, subscription id or cron expression is invalid; duplicate agent or channel names; a subscription to an unknown channel; a tool with <code>needsApproval</code></td></tr><tr><td><code>AgentNotFoundError</code></td><td><code>AGENT_NOT_FOUND</code></td><td><code>agent_not_found</code></td><td><code>dispatch()</code> for an agent the engine does not hold; <code>@chamvi/http</code> answers 404</td></tr><tr><td><code>InvalidRunStateError</code></td><td><code>INVALID_RUN_STATE</code></td><td><code>invalid_run_state</code></td><td>A run is not in the status an operation needs: resuming a run that is not waiting, cancelling a settled run, a store guard (<code>expectStatus</code>, <code>expectOwner</code>) that does not match; <code>approve()</code> outside a tool call or in a streaming tool&#39;s body; <code>emit()</code> outside a tool call</td></tr><tr><td><code>RunNotFoundError</code></td><td><code>RUN_NOT_FOUND</code></td><td><code>run_not_found</code></td><td><code>resume()</code>, <code>cancel()</code> or <code>updateRun()</code> for an unknown run</td></tr><tr><td><code>ArtifactNotFoundError</code></td><td><code>ARTIFACT_NOT_FOUND</code></td><td><code>artifact_not_found</code></td><td>An execution cannot read an artifact its messages refer to (the run fails); <code>@chamvi/http</code> answers 404 with it for an unknown artifact</td></tr><tr><td><code>BudgetExceededError</code></td><td><code>BUDGET_EXCEEDED</code></td><td><code>BudgetExceeded</code></td><td>A run hit <code>maxSteps</code> or <code>maxTokens</code> while the model still wanted tools</td></tr><tr><td><code>TimeoutError</code></td><td><code>TIMEOUT</code></td><td><code>Timeout</code></td><td>An execution exceeded <code>timeoutMs</code></td></tr><tr><td><code>FatalToolError</code></td><td><code>FATAL_TOOL</code></td><td><code>FatalToolError</code> (or a custom code)</td><td>A tool decides the run must fail</td></tr><tr><td><code>IncompleteResponseError</code></td><td><code>INCOMPLETE_RESPONSE</code></td><td><code>incomplete_response</code></td><td>The model gave no complete answer and the run fails: its stream ended without a finish part, or (with <a href="/guide/agents#structured-output">structured <code>output</code></a>) the answer was cut off at the output token limit or the loop ended on a tool call nothing executed</td></tr><tr><td><code>ToolNotAllowedError</code></td><td><code>TOOL_NOT_ALLOWED</code></td><td><code>tool_not_allowed</code></td><td>A call to a tool the agent&#39;s <code>toolPolicy</code> refuses: recorded on the tool step for a model&#39;s call to it, and returned to the model for a pending call that runs after an approval; a tool error, the run goes on</td></tr><tr><td><code>ToolDeniedError</code></td><td><code>TOOL_DENIED</code></td><td><code>tool_denied</code></td><td>A gate refused a tool call, e.g. a <code>beforeToolExecution</code> hook after a denied <a href="/guide/approvals">approval</a>; the message is the gate&#39;s, a tool error, the run goes on</td></tr><tr><td><code>ChannelNotFoundError</code></td><td><code>CHANNEL_NOT_FOUND</code></td><td><code>channel_not_found</code></td><td><code>ctx.channels.findOneOrFail()</code> named a channel the engine does not hold, or one without <code>out</code>; an approval delivery through a channel the engine no longer has (to <code>onError</code>)</td></tr><tr><td><code>LeaseLostError</code></td><td><code>LEASE_LOST</code></td><td><code>lease_lost</code></td><td>Reported to <code>onError</code> when an engine stops executing a run whose claim it lost; carries <code>runId</code></td></tr><tr><td><code>SandboxError</code></td><td><code>SANDBOX</code></td><td><code>sandbox_error</code></td><td>A <a href="/guide/workspaces">workspace</a> or its provider failed: a create, start or checkout (with git&#39;s stderr), a missing or oversized file, an unknown, expired or disposed workspace, a Docker or Kubernetes API error, a reached per-run workspace cap; a tool error, the run goes on</td></tr><tr><td><code>ValidationError</code></td><td><code>VALIDATION</code></td><td><code>validation_error</code></td><td>A state document fails its schema (carries <code>issues</code>); an invalid attachment at <code>dispatch()</code> or <code>artifacts.put()</code>; a final answer that does not parse as the agent&#39;s <a href="/guide/agents#structured-output">structured <code>output</code></a> (the run fails); a workspace path, repository or ref the sandbox rules refuse (a tool error); an <code>emit()</code> without an address off the source channel (a tool error)</td></tr></tbody></table><h2 id="run-errors" tabindex="-1">Run errors <a class="header-anchor" href="#run-errors" aria-label="Permalink to &quot;Run errors&quot;">​</a></h2><p>A failed run stores <code>{ code, message }</code> in <code>run.error</code>. For budget, timeout and fatal tool failures the code is the error&#39;s code. Any other thrown value gets its own <code>code</code> if it has a string one, else <code>Error</code>.</p><p>A run the registry cancelled stores why in <code>run.error</code> too, with a code that has no error class (nothing throws it):</p><table tabindex="0"><thead><tr><th><code>ErrorCode</code></th><th>Code</th><th>Stored when</th></tr></thead><tbody><tr><td><code>AGENT_REPLACED</code></td><td><code>agent_replaced</code></td><td>A folder change (a new revision) or a replaced code agent cancelled the run while it was unsettled</td></tr><tr><td><code>AGENT_REMOVED</code></td><td><code>agent_removed</code></td><td>The agent was removed (its folder deleted) while the run was unsettled</td></tr></tbody></table><p>A run cancelled on another replica keeps the reason once its owner settles it; a run that completes anyway ends without one. A user&#39;s cancel stores no error.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> run = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.getRun(runId);</span></span>
<span class="line"><span style="color:#FF7B84;">if</span><span style="color:#E6DFDE;"> (run?.status === RunStatus.FAILED) {</span></span>
<span class="line"><span style="color:#FF7B84;">    switch</span><span style="color:#E6DFDE;"> (run.error?.code) {</span></span>
<span class="line"><span style="color:#FF7B84;">        case</span><span style="color:#E6DFDE;"> ErrorCode.BUDGET_EXCEEDED:</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E7C58C;"> &#39;Raise maxSteps or maxTokens, or narrow the instructions.&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">        case</span><span style="color:#E6DFDE;"> ErrorCode.TIMEOUT:</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E7C58C;"> &#39;Raise timeoutMs or make the tools faster.&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">        case</span><span style="color:#E6DFDE;"> ErrorCode.FATAL_TOOL:</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E7C58C;"> \`A tool stopped the run: </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">run</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">error</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">message</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">        default</span><span style="color:#E6DFDE;">:</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E6DFDE;"> run.error?.message;</span></span>
<span class="line"><span style="color:#E6DFDE;">    }</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><h2 id="errors-without-a-caller" tabindex="-1">Errors without a caller <a class="header-anchor" href="#errors-without-a-caller" aria-label="Permalink to &quot;Errors without a caller&quot;">​</a></h2><p>Some errors happen where nobody awaits: a lost lease, a failed approval message, a listener that throws, a failed recovery pass. They go to <code>onError(error, run?)</code>, by default <code>console.error</code>. Pass your logger. A <code>LeaseLostError</code> there is informational: another replica carries the run on.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#E6DFDE;">    onError: (error, run) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">        if</span><span style="color:#E6DFDE;"> (error </span><span style="color:#FF7B84;">instanceof</span><span style="color:#E6DFDE;"> LeaseLostError) {</span></span>
<span class="line"><span style="color:#958A8B;">            // another replica carries the run on; nothing to do</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#E6DFDE;">        }</span></span>
<span class="line"><span style="color:#E6DFDE;">        logger.error({ err: error, runId: run?.id }, </span><span style="color:#E7C58C;">&#39;chamvi&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div>`,12)])])}const E=o(s,[["render",n]]);export{h as __pageData,E as default};
